import sys
from datetime import date, timedelta

RATE = {"book": 0.5, "dvd": 1.0, "magazine": 0.2}


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def adjust_due_date(due_date):
    """
    Adjust due dates that fall on a Sunday to the following Monday.
    """
    if due_date.weekday() == 6:
        return due_date + timedelta(days=1)
    return due_date


def main():
    lines = sys.stdin.read().splitlines()
    asof_date = parse(lines[0].split(" ")[1])
    totals = {}
    for line in lines[1:]:
        if not line.strip():
            continue
        member, kind, due_text, returned = line.split()
        due_date = parse(due_text)
        adjusted_due_date = adjust_due_date(due_date)
        if returned == "-":
            return_date = asof_date
        else:
            return_date = parse(returned)
        late_days = (return_date - adjusted_due_date).days
        if late_days > 0:
            fee = max(late_days - 3, 0) * RATE[kind]
            totals[member] = totals.get(member, 0) + fee
    for member in sorted(totals):
        print(f"{member} {totals[member]:.2f}")
    print(f"total {sum(totals.values()):.2f}")


if __name__ == "__main__":
    main()
